// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, 2 * amount);

        vm.prank(actor);
        (bool ok1,) = address(c).call{value: amount}(abi.encodeWithSelector(c.Put.selector, uint256(0)));
        assertTrue(ok1);

        vm.prank(actor);
        (bool ok2,) = address(c).call{value: amount}(abi.encodeWithSelector(c.Put.selector, uint256(0)));
        assertTrue(ok2);
    }
}
